package geometry;

/** Functions of points. */
public final class Geometry {
    private Geometry() {
    }

    /** Euclidean distance between two points. */
    public static double distance(Point a, Point b) {
        return Math.hypot(a.x() - b.x(), a.y() - b.y());
    }
}

