package shapes;

import java.util.List;
import java.util.function.DoubleUnaryOperator;

/** Every kind of instruction the listing decodes, in a few lines each. */
public final class Shapes {
    sealed interface Shape permits Circle, Square {}
    record Circle(double r) implements Shape {}
    record Square(double side) implements Shape {}

    static double area(Shape s) {
        return switch (s) {
            case Circle c -> Math.PI * c.r() * c.r();
            case Square q -> q.side() * q.side();
        };
    }

    static String day(int d) {
        switch (d) {
            case 1: return "Mon";
            case 2: return "Tue";
            case 3: return "Wed";
            default: return "?";
        }
    }

    static int sparse(int k) {
        switch (k) {
            case 10: return 1;
            case 1000: return 2;
            default: return 0;
        }
    }

    static int sum(int[] xs) {
        int total = 0;
        for (int i = 0; i < xs.length; i++) total += xs[i];
        return total;
    }

    static long big() {
        long x = 123456789012L;
        int[][] grid = new int[3][4];
        grid[1][2] = 7;
        return x + grid.length;
    }

    static double twice(List<Shape> shapes) {
        DoubleUnaryOperator doubled = v -> v * 2;
        double total = 0;
        for (Shape s : shapes) total += doubled.applyAsDouble(area(s));
        return total;
    }

    public static void main(String[] args) {
        System.out.println(twice(List.of(new Circle(1), new Square(2))) + " " + day(2) + sparse(1000) + sum(new int[] {1, 2, 3}) + big());
    }
}
